package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaZhDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sajdah_tilawah" to DuaText("持诵斋戒", "我的脸已经屈服于创造它的那一位，并通过他的力量和力量带来了它的听觉和视觉。", "顶礼诵经中。", "先知（愿主福安之）ﷺ 在夜间大礼拜时说这番话。"),
        "dua_after_witr" to DuaText("维特尔之后", "荣耀归于至圣君王。", "witr 萨拉姆之后三次，第三次提高声音。", "先知 ﷺ 在 witr 之后说了这句话。"),
        "dua_tahajjud_nur" to DuaText("塔哈吉德开场祈请文", "安拉啊，赞美属于你；你是天地万物的维持者。赞美属于你；你是诸天、大地和天地万物的光。赞美属于你；你是真理，你的应许是真实的，与你的会面是真实的，你的话是真实的，天堂是真实的，地狱是真实的，先知是真实的，穆罕默德ﷺ是真实的，时刻是真实的。", "当开始夜间祈祷（tahajjud）（杜阿的开头部分）时。", "先知 ﷺ 在起立参加 tahajjud 时背诵了这一点（完整的杜阿在《布哈里圣训实录》中）。"),
        "dua_rabba_jibrail" to DuaText("指导我解决争议问题", "安拉啊，吉布里勒、米凯勒和伊斯拉菲尔的主宰，天地的创造者，看不见和看见的人的知晓者！你将根据你的仆人们过去的不同来判断他们。请引导我了解分歧的真相。事实上，您会引导您所愿意的人走上正路。", "在 tahajjud 开始时——在分歧中寻求真相的指导。", "先知 ﷺ 以这句杜阿开始了他的夜间祈祷。"),
        "dua_going_to_mosque_nur" to DuaText("去清真寺（光之杜阿）", "安拉啊，请把光放在我的心里，光在我的眼睛里，光在我的耳朵里，光在我的右边，光在我的左边，光在我的上方，光在我的下方，光在我的前面，光在我的后面，并为我带来光。", "去清真寺做晨礼的时候。", "先知 ﷺ 在外出祈祷时背诵了这句话。"),
        "dua_waswasa_salah" to DuaText("礼拜期间的瓦瓦萨 (Khinzab)", "我向安拉寻求庇护，免受邪恶之徒的伤害。", "当祈祷期间出现撒旦低语时，寻求庇护并向左侧轻轻吐口水三遍。", "Uthman ibn Abil-'As (RA) 这样做了，窃窃私语就消失了。"),
        "dua_alimal_ghayb" to DuaText("未见者知者", "安拉啊，看不见和看见的全知者，天地的创造者，万物的主宰和主宰！我见证除你以外绝无应受崇拜的神。我向你寻求庇护，免受我自己的邪恶，以及恶魔的邪恶和他的（召唤）逃避。", "早上、晚上和睡觉前——先知 ﷺ 将其教导给艾布伯克尔 (RA)。", "保护免受自我和恶魔的邪恶。"),
        "dua_fitratil_islam" to DuaText("伊斯兰教开斋节", "我们进入了伊斯兰教的开斋节、真诚的话语、我们的先知穆罕默德 ﷺ 的宗教以及我们的父亲易卜拉欣 (AS) 的道路，他是正直的穆斯林，不是多神教徒。", "在早晨。", "每天早晨更新自己的信念。"),
        "dua_amsayna_fitrah" to DuaText("伊斯兰教的开斋节之夜", "我们进入了伊斯兰教的开斋节、真诚的话语、我们的先知穆罕默德 ﷺ 的宗教以及我们的父亲易卜拉欣 (AS) 的道路，他是正直的穆斯林，不是多神教徒。", "晚上。", "每天晚上更新自己的信念。"),
        "dua_tahleel_10_fajr" to DuaText("晨礼和昏礼之后的十塔利尔", "除了真主之外，没有人有权利被崇拜，独自一人，没有伴侣。统治权属于他，赞美也属于他；他赐予生命并导致死亡，他拥有掌管万物的力量。", "晨礼（和昏礼）后十次，在离开坐姿或说话之前。", "十件善事，十件罪孽被消除，十件等级提升，全天免受恶魔的保护。"),
        "dua_la_hawla_kanz" to DuaText("詹纳的宝藏", "除了安拉之外，没有任何力量和能力。", "经常，任何时候。", "它是天堂的瑰宝之一。"),
        "dua_four_beloved_words" to DuaText("最爱的四个字", "荣耀归于真主，一切赞美归于真主，除真主外，没有人有权受崇拜，真主是最伟大的。", "安拉最喜爱的话语。", "对于先知 ﷺ 来说，它们比太阳升起的一切都更珍贵。"),
        "dua_two_light_words" to DuaText("舌尖上的两个字", "荣耀归于真主，一切赞美都归于他；荣耀归于伟大的真主。", "舌头上轻，音阶上重。", "至仁至慈的挚爱，舌头上轻，天平上重。 （布哈里圣训最后的圣训）"),
        "dua_ya_dhal_jalal" to DuaText("亚达尔·贾拉利·瓦尔·伊克拉姆", "哦，威严和荣耀的拥有者！", "在 dua 中坚持下去——先知的 ﷺ 指令。", "先知 ﷺ 说：坚持“Ya Dhal-Jalali wal-Ikram”。"),
        "dua_sleep_wadatu_janbi" to DuaText("以你之名我躺下", "我的主，奉你的名，我躺下，奉你的名，我站起来。如果你带走我的灵魂，请怜悯它；如果你释放它，请像保护你正义的仆人一样保护它。", "掸掉床上的灰尘后，躺下。", "睡前将自己的灵魂托付给安拉。"),
        "dua_sleep_khalaqta_nafsi" to DuaText("你创造了我的灵魂", "安拉啊，您创造了我的灵魂，您将带走它。它的死亡和生命都属于你。如果你让它活着，就保护它；如果你让它死，就原谅它。安拉啊，我祈求你的幸福。", "睡觉之前 — 由伊本·奥马尔 (RA) 讲述。", "先知 ﷺ 指示在睡前说这句话。"),
        "dua_sleep_atamana" to DuaText("睡前感恩", "所有的赞美都归于安拉，他给了我们食物，给了我们饮料，满足了我们，给了我们庇护。有多少人没有人可以满足他们的需要或为他们提供庇护。", "睡觉时。", "先知 ﷺ 在睡觉时说了这句话。"),
        "dua_sleep_rabbas_samawat" to DuaText("天上的主——偿还我们的债", "安拉啊，诸天、大地和强大宝座的主宰，我们的主和万物的主，种子和枣核的分裂者，托拉、引支勒和弗尔坎的启示者！我向你寻求庇护，免受你所持有的一切邪恶之害。安拉啊，你是第一位的，在你之前没有任何事物；你是最后的，在你之后没有任何东西；你是显圣者，没有什么高于你；你是隐藏者，没有什么对你隐藏。为我们还清债务，让我们摆脱贫困。", "睡觉前，右侧卧 — 教给法蒂玛 (RA)。", "减轻债务和困难的二重奏。"),
        "dua_sleep_fear" to DuaText("睡眠中的恐惧或不安", "我寻求安拉完美话语的庇护，免受他的愤怒和惩罚，免受他仆人的邪恶，来自魔鬼的低语和他们对我的攻击。", "当在睡眠中感到恐惧或不安时。", "这样做的话，那东西就不会伤害他了。"),
        "dua_waking_afani" to DuaText("苏醒：他恢复了我的灵魂", "所有的赞美都归于真主，他赐予了我身体的健康，将我的灵魂归还给我，并让我记住了他。", "醒来时。", "感谢新的早晨。"),
        "dua_allahu_rabbi" to DuaText("安拉，安拉是我的主", "安拉，安拉是我的主；我与他没有任何关联。", "在悲伤或痛苦中——先知 ﷺ 将其教导给阿斯玛·本特·乌迈斯 (RA)。", "危难时刻，坚守贞洁。"),
        "dua_rahmataka_arju" to DuaText("我希望得到你的怜悯", "安拉啊，我祈求您的仁慈，请不要让我独自一人，哪怕只是一眨眼的时间，并安排好我的一切事务。除了你以外，再没有神。", "遇险者的杜阿 (Da'awat al-makrub)。", "先知 ﷺ 称其为遇险者的杜阿。"),
        "dua_against_enemy_ahzab" to DuaText("对抗敌军", "安拉啊，经典的启示者，计算迅速！击败同盟军。安拉啊，击败他们并动摇他们。", "对抗敌人——南方邦联之战的二重奏。", "先知的 ﷺ dua 对抗敌人。"),
        "dua_anta_adudi" to DuaText("你是我的支持", "安拉啊，你是我的支持者和帮助者。靠你我谋划，靠你我前进，靠你我战斗。", "在比赛或重大挑战之前。", "先知 ﷺ 在战斗中说了这句话。"),
        "dua_ikfinihim" to DuaText("我对付他们就够了", "安拉啊，无论你如何，我都足以对抗他们了。", "对抗压迫者的邪恶——《沟渠里的人们》故事中男孩的杜阿。", "安拉从压迫者手中拯救了这个男孩。"),
        "dua_qadarullah" to DuaText("当不好的事情发生时", "这是安拉的法令，他按照他的意愿行事。", "当发生不愉快的事情时，不要说“如果就好了”。", "“如果只是”打开了通往恶魔的大门。"),
        "dua_ala_kulli_hal" to DuaText("任何情况下的赞美", "在任何情况下，所有的赞美都是归给安拉的。", "当不喜欢的事情发生时。", "先知ﷺ在面对他不喜欢的事情时这么说。"),
        "dua_dogs_barking" to DuaText("晚上听到狗叫声", "我向安拉寻求庇护，免受邪恶之徒的伤害。", "夜间听到狗叫或驴叫时。", "他们看到了你看不到的东西。"),
        "dua_leaving_home_adilla" to DuaText("避免误入歧途的避难所", "安拉啊，我向你寻求庇护，以免我误入歧途或被引入歧途，以免我失足或被逼失足，以免我做错事或被冤枉，以免我做出愚蠢的行为或被愚蠢地对待。", "离开家时 — 由 Umm Salamah (RA) 叙述。", "先知 ﷺ 每当他离开家时都会背诵这句话。"),
        "dua_ascending_descending" to DuaText("上升和下降", "安拉是最伟大的（上升时）。 ——荣耀归于真主（降临时）。", "在旅途中，上山时说“Allahu Akbar”，下山时说“SubhanAllah”。", "旅伴(RA)旅行时的做法。"),
        "dua_traveller_sahar" to DuaText("黎明前旅行者的杜阿", "听众听到（并传递）了我们对安拉的赞美和他对我们的恩惠。我们的主，请陪伴我们并赐予我们您的恩惠——（我这样说）寻求真主的庇护，免受火狱的伤害。", "黎明前，旅途中。", "先知 ﷺ 在黎明前旅行时说了这句话。"),
        "dua_zawwadakallah" to DuaText("致旅行者：愿真主赐予Taqwa", "愿真主为您的旅程提供 taqwa，宽恕您的罪过，让您无论身在何处都能轻松过日子。", "告别旅人时。", "先知 ﷺ 将这个 dua 送给了一个即将踏上旅程的人。"),
        "dua_traveller_to_resident" to DuaText("旅行者给留下来的人", "我将你托付给阿拉，对他的信任永远不会消失。", "这是旅人告别家人时说的。", "将家庭的安全托付给安拉。"),
        "dua_entering_village" to DuaText("进入城镇或村庄", "安拉啊，七层天和它们所遮蔽的一切的主宰，七大地和它们承载的一切的主宰，魔鬼和它们误导的一切的主宰，风和它们驱散的一切的主宰！我们向你祈求这座城市及其人民的福祉，并寻求你的庇护，使其免受其邪恶、其人民的邪恶以及城内事物的邪恶。", "在进入城镇或城市之前。", "先知 ﷺ 每当他想要进入一个城镇时都会背诵这句话。"),
        "dua_vehicle_stumbles" to DuaText("当车辆绊倒时", "以安拉的名义。", "当坐骑或车辆滑倒或绊倒时，不要说“愿恶魔灭亡”。", "念出“比斯米拉”会让恶魔缩小到苍蝇大小。"),
        "dua_ajz_kasal_haram" to DuaText("远离虚弱和年老", "安拉啊，我向你寻求庇护，免遭无助和懒惰、怯懦和年老、生与死的考验以及坟墓的惩罚。", "全面的每日避难所。", "先知 ﷺ 经常发出的二音。"),
        "dua_sharri_ma_amiltu" to DuaText("远离我的恶行", "安拉啊，我向你寻求庇护，使我免受我所做之事和我未做之事的邪恶。", "根据艾莎 (RA)，先知 ﷺ 的二重奏。", "保护免受已完成事项和未完成事项的后果的影响。"),
        "dua_jahdil_bala" to DuaText("躲避严峻考验", "安拉啊，我向你寻求庇护，使我免于严峻的考验，免遭苦难，免遭邪恶的法令，免遭敌人的幸灾乐祸。", "躲避严峻的考验和敌人的幸灾乐祸。", "先知 ﷺ 寻求庇护以避免这四件事。"),
        "dua_fitnat_ghina_faqr" to DuaText("逃避财富和贫穷的考验", "安拉啊，我向你寻求庇护，免遭懒惰和年老、罪恶和债务、坟墓的审判和惩罚、火狱的审判和惩罚、财富审判的邪恶和贫穷的审判。", "逃离坟墓、地狱、财富和贫穷的考验（杜阿的一部分）。", "对先知 ﷺ 的全面庇护。"),
        "dua_kufr_faqr" to DuaText("远离怀疑和贫穷", "安拉啊，我向你寻求庇护，使我免受怀疑和贫穷，我向你寻求庇护，使我免受坟墓的惩罚。除了你以外，再没有神。", "早晚各三次。", "艾布·伯克拉 (Abu Bakrah) (RA) 听到先知 ﷺ 这么说。"),
    )
}
